import { useState } from "react"
import { useTranslation } from "react-i18next"
import { ArrowLeftIcon, LogOutIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { logoutPlatform, usePlatformAuth } from "../auth/store"
import { UpdatesRow } from "./updates"
import app from "../../alwith.app.json"

/** Default settings page; application authors may replace this whole component. */
export function SettingsPage({onClose}: {onClose: () => void}) {
  const {i18n, t} = useTranslation()
  const account = usePlatformAuth(state => state.user?.login_email)
  const [error, setError] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const zh = i18n.language.startsWith("zh")
  async function signOut() {
    setBusy(true); setError(null)
    try { await logoutPlatform() } catch (error) { setError(error instanceof Error ? error.message : String(error)) } finally { setBusy(false) }
  }
  return <section className="flex h-full min-h-0 flex-col">
    <header className="flex h-12 shrink-0 items-center gap-2 border-b px-4" data-tauri-drag-region>
      <Button variant="ghost" size="icon" onClick={onClose} aria-label={zh ? "返回聊天" : "Back to chat"}><ArrowLeftIcon /></Button>
      <h1 className="text-sm font-medium">{t("settings")}</h1>
    </header>
    <div className="mx-auto flex w-full max-w-2xl flex-col gap-6 overflow-y-auto p-6">
      <div className="flex items-center justify-between gap-4">
        <div className="min-w-0"><h2 className="text-sm font-medium">{zh ? "账号" : "Account"}</h2><p className="truncate text-sm text-muted-foreground">{account}</p></div>
        <Button variant="outline" disabled={busy} onClick={() => void signOut()}><LogOutIcon data-icon="inline-start"/>{t("signOut")}</Button>
      </div>
      <div className="flex items-center justify-between gap-4">
        <h2 className="text-sm font-medium">{zh ? "语言" : "Language"}</h2>
        <Tabs value={zh ? "zh-CN" : "en"} onValueChange={value => void i18n.changeLanguage(value)}>
          <TabsList aria-label={zh ? "语言" : "Language"}>{app.languages.map(language => <TabsTrigger key={language} value={language}>{language === "zh-CN" ? "中文" : "English"}</TabsTrigger>)}</TabsList>
        </Tabs>
      </div>
      <div className="flex items-center justify-between gap-4"><h2 className="text-sm font-medium">{zh ? "外观" : "Appearance"}</h2><span className="text-sm text-muted-foreground">{zh ? "跟随系统" : "System appearance"}</span></div>
      {"updates" in app && <UpdatesRow />}
      {error && <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert>}
    </div>
  </section>
}

import { checkForUpdates, installUpdate, type DesktopUpdate } from "@alwith/module-desktop-shell"
import { useState } from "react"
import { useTranslation } from "react-i18next"
import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"
import app from "../../alwith.app.json"

type Status =
  | { kind: "idle" | "checking" | "upToDate" }
  | { kind: "available" | "installing"; update: DesktopUpdate }
  | { kind: "failed"; message: string }

/** Manual update check against the app's GitHub release manifest; the shell downloads, verifies, installs and relaunches. */
export function UpdatesRow() {
  const { t } = useTranslation()
  const [status, setStatus] = useState<Status>({ kind: "idle" })
  const busy = status.kind === "checking" || status.kind === "installing"
  const fail = (error: unknown) => setStatus({ kind: "failed", message: error instanceof Error ? error.message : String(error) })
  async function check() {
    setStatus({ kind: "checking" })
    try { const update = await checkForUpdates(); setStatus(update ? { kind: "available", update } : { kind: "upToDate" }) } catch (error) { fail(error) }
  }
  async function install(update: DesktopUpdate) {
    setStatus({ kind: "installing", update })
    try { await installUpdate() } catch (error) { fail(error) }
  }
  const caption = status.kind === "checking" ? t("updates.checking")
    : status.kind === "upToDate" ? t("updates.upToDate", { version: app.version })
    : status.kind === "available" ? t("updates.available", { version: status.update.version })
    : status.kind === "installing" ? t("updates.installing", { version: status.update.version })
    : status.kind === "failed" ? status.message
    : t("updates.version", { version: app.version })
  return <div className="flex items-center justify-between gap-4">
    <div className="min-w-0">
      <h2 className="text-sm font-medium">{t("updates.title")}</h2>
      <p className={`truncate text-sm ${status.kind === "failed" ? "text-destructive" : "text-muted-foreground"}`} role="status">{caption}</p>
    </div>
    <Button variant="outline" disabled={busy} onClick={() => void (status.kind === "available" ? install(status.update) : check())}>
      {busy && <Spinner data-icon="inline-start" />}
      {t(status.kind === "available" ? "updates.install" : "updates.check")}
    </Button>
  </div>
}
